#!/usr/bin/env node
// Every generated file is checked against its generator in CI (R1188-U8).
//
// Bulk changes are made by rules: a generator with `--write`, whose `--check`
// regenerates and compares. A file says it is generated in its first lines:
// ``Generated by `<command>` ``. This gate finds every such file and fails
// unless the generator the command names is run by a registered CI gate
// (data/meta/ci-gates/*.lino) or a workflow step, so a hand edit of a
// generated file cannot be merged. A generator that cannot run in CI (it
// reads the operator's session history, or writes from an authenticated API)
// is listed in data/meta/generated-files.lino with the reason.
//
// Usage: node scripts/check-generated-files.mjs [--list]

import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const EXCEPTIONS = 'data/meta/generated-files.lino';
const HEADER_LINES = 12;

/** Paths that hold captured evidence and logs, never generated sources. */
const EVIDENCE = /^(?:dev\/log|data\/cache|data\/view)\/|\/(?:raw-data|test-logs)\/|\.(?:log|jsonl|ndjson|html|png|jpg|wasm|json|lock)$/u;

/**
 * The generator command a file's header names, or null.
 * @param {string} text
 * @returns {string | null}
 */
export function generatorOf(text) {
  const head = text.split('\n').slice(0, HEADER_LINES).join('\n');
  const command = /Generated by `([^`]+)`/u.exec(head)?.[1] ?? null;
  // A placeholder (`<command>`) is the convention quoted, not a generator.
  return command === null || /^<[^>]*>$/u.test(command) ? null : command;
}

/**
 * The script a generator command runs, without its extension
 * (`rust-script scripts/render-status.rs --write` gives `scripts/render-status`).
 * @param {string} command
 * @returns {string | null}
 */
export function scriptOf(command) {
  return /(?:scripts|experiments)\/[\w./-]+?(?=\.(?:rs|mjs|py|sh|js)\b)/u.exec(command)?.[0] ?? null;
}

/**
 * Whether CI runs the script or its twin of the same base name under scripts/.
 * @param {string} script
 * @param {string} ciText the gate registry and the workflows, concatenated
 * @returns {boolean}
 */
export function checkedInCi(script, ciText) {
  const base = script.split('/').pop();
  return ciText.includes(`${script}.`) || ciText.includes(`scripts/${base}.`);
}

/**
 * The excepted paths and their reasons.
 * @param {string} lino
 * @returns {Map<string, string>}
 */
export function exceptionsFrom(lino) {
  const exceptions = new Map();
  let path = null;
  for (const line of lino.split('\n')) {
    const file = /^ {2}unchecked "([^"]+)"\s*$/u.exec(line);
    const reason = /^ {4}reason "([^"]+)"\s*$/u.exec(line);
    if (file) {
      path = file[1];
      exceptions.set(path, '');
    } else if (reason && path) {
      exceptions.set(path, reason[1]);
    }
  }
  return exceptions;
}

/**
 * The problems of a set of files.
 * @param {Array<{path: string, text: string}>} files
 * @param {string} ciText
 * @param {Map<string, string>} exceptions
 * @returns {{generated: Array<{path: string, command: string, checked: boolean}>, problems: Array<string>}}
 */
export function generatedFileProblems(files, ciText, exceptions) {
  const generated = [];
  const problems = [];
  for (const { path, text } of files) {
    const command = generatorOf(text);
    if (command === null) {
      continue;
    }
    const script = scriptOf(command);
    const checked = script !== null && checkedInCi(script, ciText);
    generated.push({ path, command, checked });
    if (checked && exceptions.has(path)) {
      problems.push(`${path} is listed as unchecked in ${EXCEPTIONS}, but CI checks it now; remove the row`);
    } else if (!checked && !exceptions.has(path)) {
      problems.push(`${path} is generated by \`${command}\`, which no CI gate or workflow runs; register its --check as a gate`);
    } else if (!checked && exceptions.get(path) === '') {
      problems.push(`${path} is listed as unchecked in ${EXCEPTIONS} without a reason`);
    }
  }
  const seen = new Set(files.map((file) => file.path));
  for (const path of exceptions.keys()) {
    if (!seen.has(path)) {
      problems.push(`${EXCEPTIONS} lists ${path}, which is not a generated file in the tree; remove the row`);
    }
  }
  return { generated, problems };
}

function main(argv) {
  const root = join(dirname(fileURLToPath(import.meta.url)), '..');
  const listed = (args) =>
    execFileSync('git', ['ls-files', '--cached', '--others', '--exclude-standard', ...args], {
      cwd: root,
      encoding: 'utf8',
      maxBuffer: 1 << 28,
    })
      .split('\n')
      .filter(Boolean);
  const read = (path) => {
    try {
      return readFileSync(join(root, path), 'utf8');
    } catch {
      return '';
    }
  };
  const files = listed([])
    .filter((path) => !EVIDENCE.test(path))
    .map((path) => ({ path, text: read(path) }));
  const ciText = listed(['data/meta/ci-gates', '.github/workflows']).map(read).join('\n');
  const { generated, problems } = generatedFileProblems(files, ciText, exceptionsFrom(read(EXCEPTIONS)));
  if (argv.includes('--list')) {
    for (const entry of generated) {
      console.log(`${entry.checked ? 'checked  ' : 'unchecked'} ${entry.path} <- ${entry.command}`);
    }
  }
  for (const problem of problems) {
    console.error(`::error::${problem}`);
  }
  const checked = generated.filter((entry) => entry.checked).length;
  console.log(`generated files: ${generated.length}, ${checked} checked in CI, ${generated.length - checked} listed as unchecked`);
  return problems.length ? 1 : 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  process.exitCode = main(process.argv.slice(2));
}
